    {
      "name": "Pharmaceuticals & Biotech",
      "impact": "headwind",
      "rationale": "Specific, deep price cuts (50-85%) on major drugs by Novo Nordisk, Pfizer, Eli Lilly and others directly threaten US revenue and margins."
    },
    {
      "name": "Grocery & Consumer Staples Retail",
      "impact": "headwind",
      "rationale": "Widespread price cuts by Walmart, Target, Kroger, and others signal margin compression and intense price competition in essentials."
    },
    {
      "name": "Packaged Foods & Beverages",
      "impact": "headwind",
      "rationale": "PepsiCo's 15% snack price cut exemplifies pressure; broader industry weakness if large retailers demand concessions."
    },
    {
      "name": "Automakers (Traditional)",
      "impact": "headwind",
      "rationale": "Ford employee pricing and GM/Stellantis deferred-payment financing incentives directly erode per-unit profitability."
    },
    {
      "name": "Utilities (Rate-Regulated)",
      "impact": "headwind",
      "rationale": "Explicit rate freezes or customer returns (Alliant, DTE, Entergy) cap revenue growth in those jurisdictions."
    },
    {
      "name": "Broad Consumer Discretionary",
      "impact": "tailwind",
      "rationale": "Lower food, drug, and energy costs boost real disposable income, potentially freeing up spending for other goods and services."
    }
  ],
